sys_variable_value.value:
(function execute(inputs, outputs) {
var times = []; 
var base = new GlideDateTime(inputs.reminder_time); 
if (inputs.frequency === 'once_Daily') { 
times.push(base.getValue()); 
} else if (inputs.frequency === 'twice_Daily') { 
times.push(base.getValue()); 
var second = new GlideDateTime(inputs.reminder_time); 
second.addSeconds(43200); // +12 hours 
times.push(second.getValue()); 
} else if (inputs.frequency === 'thrice_Daily') { 
times.push(base.getValue()); 
var dose2 = new GlideDateTime(inputs.reminder_time); 
dose2.addSeconds(28800); // +8 hours 
times.push(dose2.getValue()); 
var dose3 = new GlideDateTime(inputs.reminder_time); 
dose3.addSeconds(57600); // +16 hours 
times.push(dose3.getValue()); 
} 
outputs.dose_times = JSON.stringify(times);
})(inputs, outputs);

